T['b-odpornosc'] = dict(F=[
 ('Wyjaśnij pojęcie: odporność nieswoista', 'Wrodzone mechanizmy obrony działające na każdy patogen tak samo i natychmiast: bariery (skóra, śluz, HCl, lizozym), fagocytoza, stan zapalny, gorączka, układ dopełniacza, interferony, komórki NK.'),
 ('Wyjaśnij pojęcie: odporność swoista', 'Nabyta odpowiedź skierowana przeciw konkretnemu antygenowi, z udziałem limfocytów T i B, rozwijająca się z opóźnieniem i tworząca pamięć immunologiczną.'),
 ('Wyjaśnij pojęcie: antygen', 'Substancja (najczęściej białko lub wielocukier) rozpoznawana przez układ odpornościowy jako obca i wywołująca odpowiedź swoistą.'),
 ('Wyjaśnij pojęcie: przeciwciało', 'Immunoglobulina — białko wytwarzane przez komórki plazmatyczne (z limfocytów B), wiążące swoiście antygen.'),
 ('Budowa przeciwciała', 'Dwa łańcuchy ciężkie i dwa lekkie połączone mostkami disiarczkowymi (kształt Y); regiony zmienne tworzą dwa miejsca wiązania antygenu.'),
 ('Sposoby działania przeciwciał', 'Neutralizacja toksyn i wirusów, aglutynacja (zlepianie) komórek, precypitacja, opsonizacja (ułatwienie fagocytozy), aktywacja dopełniacza.'),
 ('Gdzie dojrzewają limfocyty B i T?', 'Powstają w szpiku kostnym; limfocyty B dojrzewają w szpiku, limfocyty T — w grasicy.'),
 ('Funkcja limfocytów T pomocniczych (Th, CD4)', 'Rozpoznają antygen prezentowany przez komórki prezentujące i wydzielają cytokiny aktywujące limfocyty B i Tc oraz makrofagi — koordynują odpowiedź.'),
 ('Funkcja limfocytów T cytotoksycznych (Tc, CD8)', 'Rozpoznają i niszczą komórki zakażone wirusami i nowotworowe (odpowiedź komórkowa).'),
 ('Wyjaśnij pojęcie: odpowiedź humoralna i komórkowa', 'Humoralna — przeciwciała wytwarzane przez komórki plazmatyczne, działające w płynach ustrojowych; komórkowa — niszczenie zakażonych komórek przez limfocyty Tc.'),
 ('Wyjaśnij pojęcie: komórki pamięci', 'Długo żyjące limfocyty B i T powstałe podczas odpowiedzi pierwotnej, umożliwiające szybką i silną odpowiedź wtórną przy ponownym kontakcie z antygenem.'),
 ('Odpowiedź pierwotna a wtórna', 'Wtórna jest szybsza, silniejsza (więcej przeciwciał, głównie IgG) i dłuższa dzięki komórkom pamięci.'),
 ('Wyjaśnij pojęcie: komórki prezentujące antygen', 'Makrofagi, komórki dendrytyczne i limfocyty B — fagocytują patogen i prezentują jego fragmenty na białkach MHC II limfocytom Th.'),
 ('Wyjaśnij pojęcie: białka MHC (zgodności tkankowej)', 'Białka błonowe prezentujące fragmenty antygenów limfocytom T; MHC I — na wszystkich komórkach jądrzastych, MHC II — na komórkach prezentujących antygen. Odpowiadają za odrzucanie przeszczepów.'),
 ('Etapy stanu zapalnego', 'Uszkodzenie → uwolnienie histaminy przez komórki tuczne → rozszerzenie i zwiększona przepuszczalność naczyń (zaczerwienienie, obrzęk, ciepło, ból) → napływ fagocytów (neutrofili, makrofagów).'),
 ('Wyjaśnij pojęcie: interferony', 'Białka wydzielane przez komórki zakażone wirusem, chroniące sąsiednie komórki przed namnażaniem się wirusa.'),
 ('Wyjaśnij pojęcie: odporność czynna naturalna', 'Wytworzona po przechorowaniu — organizm sam wytwarza przeciwciała i komórki pamięci.'),
 ('Wyjaśnij pojęcie: odporność czynna sztuczna', 'Wytworzona po szczepieniu — organizm wytwarza przeciwciała i komórki pamięci w reakcji na antygeny szczepionki; długotrwała.'),
 ('Wyjaśnij pojęcie: odporność bierna naturalna', 'Przeciwciała otrzymane od matki — przez łożysko (IgG) i z mlekiem (IgA); krótkotrwała.'),
 ('Wyjaśnij pojęcie: odporność bierna sztuczna', 'Podanie gotowych przeciwciał (surowica odpornościowa, np. przeciwtężcowa, przeciw jadowi żmii) — działa natychmiast, ale krótko; brak pamięci.'),
 ('Kiedy stosuje się surowicę, a kiedy szczepionkę?', 'Surowicę — gdy potrzebna jest natychmiastowa ochrona po zakażeniu lub zatruciu; szczepionkę — profilaktycznie, by wytworzyć długotrwałą odporność.'),
 ('Wyjaśnij pojęcie: szczepionka', 'Preparat zawierający antygeny patogenu (zabite lub osłabione drobnoustroje, ich fragmenty, toksoidy, mRNA kodujące antygen) wywołujący odporność czynną.'),
 ('Wyjaśnij pojęcie: alergia', 'Nadmierna reakcja układu odpornościowego na nieszkodliwy antygen (alergen) — przeciwciała IgE na komórkach tucznych powodują uwalnianie histaminy.'),
 ('Wyjaśnij pojęcie: choroba autoimmunizacyjna', 'Choroba, w której układ odpornościowy atakuje własne komórki i tkanki — np. cukrzyca typu 1, RZS, stwardnienie rozsiane, choroba Hashimoto.'),
 ('Wyjaśnij pojęcie: AIDS — mechanizm', 'HIV zakaża limfocyty Th (CD4) i niszczy je; spadek ich liczby osłabia całą odpowiedź swoistą — rozwijają się zakażenia oportunistyczne i nowotwory.'),
 ('Wyjaśnij pojęcie: grupy krwi AB0', 'Określane przez antygeny A i B na erytrocytach; w osoczu występują przeciwciała przeciw antygenom nieobecnym (np. grupa A ma anty-B).'),
 ('Kto jest uniwersalnym dawcą i biorcą krwi (AB0)?', 'Dawca — grupa 0 (brak antygenów A i B); biorca — AB (brak przeciwciał anty-A i anty-B). W praktyce przetacza się krew jednoimienną.'),
 ('Wyjaśnij pojęcie: konflikt serologiczny Rh', 'Matka Rh⁻ uczulona antygenem D płodu Rh⁺ (zwykle przy pierwszym porodzie) wytwarza przeciwciała anty-D, które w kolejnej ciąży z płodem Rh⁺ przechodzą przez łożysko i niszczą jego erytrocyty.'),
 ('Jak zapobiega się konfliktowi serologicznemu?', 'Matce Rh⁻ po porodzie dziecka Rh⁺ (i w trakcie ciąży) podaje się immunoglobulinę anty-D, która usuwa erytrocyty płodu, zanim matka wytworzy własne przeciwciała i komórki pamięci.'),
 ('Narządy limfatyczne', 'Pierwotne: szpik kostny, grasica; wtórne: węzły chłonne, śledziona, migdałki, kępki Peyera.'),
 ('Wyjaśnij pojęcie: przeszczep a odrzucenie', 'Limfocyty T rozpoznają obce białka MHC przeszczepu jako antygeny; stosuje się dobór zgodnych dawców i leki immunosupresyjne.'),
], Q=[
 ('Przeciwciała wytwarzane są przez:', ['limfocyty Tc', '*komórki plazmatyczne', 'makrofagi', 'erytrocyty'], 'Zróżnicowane limfocyty B.'),
 ('Limfocyty T dojrzewają w:', ['szpiku kostnym', '*grasicy', 'śledzionie', 'wątrobie'], 'Grasica.'),
 ('Odporność uzyskana po podaniu surowicy przeciwtężcowej to odporność:', ['czynna sztuczna', '*bierna sztuczna', 'czynna naturalna', 'bierna naturalna'], 'Gotowe przeciwciała.'),
 ('HIV niszczy przede wszystkim:', ['erytrocyty', 'limfocyty B', '*limfocyty T pomocnicze', 'neutrofile'], 'CD4.'),
 ('Osoba z grupą krwi A ma w osoczu przeciwciała:', ['anty-A', '*anty-B', 'anty-A i anty-B', 'brak'], 'Przeciw nieobecnemu antygenowi.'),
 ('Szybsza i silniejsza odpowiedź wtórna wynika z obecności:', ['interferonów', '*komórek pamięci', 'histaminy', 'dopełniacza'], 'Pamięć immunologiczna.'),
], pp='XI.2.2')

T['b-oddychanie-czl'] = dict(F=[
 ('Odcinki układu oddechowego człowieka', 'Drogi oddechowe: jama nosowa → gardło → krtań → tchawica → oskrzela → oskrzeliki; część oddechowa: pęcherzyki płucne.'),
 ('Funkcje jamy nosowej', 'Ogrzewanie, nawilżanie i oczyszczanie powietrza (śluz, rzęski, włosy), odbiór bodźców węchowych.'),
 ('Budowa tchawicy związana z funkcją', 'Chrzęstne półpierścienie (utrzymują drożność, z tyłu miękka ściana — przełyk), nabłonek migawkowy z komórkami kubkowymi (śluz).'),
 ('Funkcja krtani', 'Przewodzenie powietrza, wytwarzanie głosu (fałdy głosowe), nagłośnia zamyka wejście do krtani podczas połykania.'),
 ('Adaptacje pęcherzyków płucnych do wymiany gazowej', 'Ogromna powierzchnia (ok. 70–100 m²), cienka ściana z nabłonka jednowarstwowego płaskiego, gęsta sieć naczyń włosowatych, wilgotna powierzchnia, surfaktant.'),
 ('Wyjaśnij pojęcie: surfaktant', 'Substancja (fosfolipidy i białka) wyściełająca pęcherzyki, obniżająca napięcie powierzchniowe — zapobiega zapadaniu się pęcherzyków.'),
 ('Wyjaśnij pojęcie: opłucna', 'Podwójna błona surowicza (płuco i ściana klatki piersiowej) z płynem w jamie opłucnej — zmniejsza tarcie i sprawia, że płuca podążają za ruchami klatki piersiowej.'),
 ('Wyjaśnij pojęcie: odma opłucnowa', 'Dostanie się powietrza do jamy opłucnej — wyrównanie ciśnień powoduje zapadnięcie się płuca.'),
 ('Mechanizm wdechu', 'Skurcz przepony (spłaszcza się) i mięśni międzyżebrowych zewnętrznych (unoszą żebra) → zwiększa się objętość klatki → ciśnienie w płucach spada poniżej atmosferycznego → powietrze napływa.'),
 ('Mechanizm wydechu spoczynkowego', 'Bierny: rozkurcz przepony i mięśni międzyżebrowych → objętość klatki maleje → ciśnienie w płucach rośnie → powietrze wypływa. Wydech nasilony — udział mięśni międzyżebrowych wewnętrznych i brzucha.'),
 ('Wyjaśnij pojęcie: wymiana gazowa zewnętrzna i wewnętrzna', 'Zewnętrzna — między powietrzem w pęcherzykach a krwią; wewnętrzna — między krwią a komórkami tkanek; obie zachodzą przez dyfuzję zgodnie z gradientem ciśnień parcjalnych.'),
 ('Jak transportowany jest tlen we krwi?', 'Prawie w całości związany z hemoglobiną erytrocytów (oksyhemoglobina), w niewielkim stopniu rozpuszczony w osoczu.'),
 ('Jak transportowany jest CO₂ we krwi?', 'Głównie jako jony wodorowęglanowe HCO₃⁻ w osoczu (ok. 70%), częściowo związany z hemoglobiną (karbaminohemoglobina) i rozpuszczony w osoczu.'),
 ('Rola anhydrazy węglanowej', 'Enzym erytrocytów katalizujący reakcję CO₂ + H₂O ⇄ H₂CO₃ ⇄ H⁺ + HCO₃⁻ — umożliwia szybki transport CO₂ jako wodorowęglanów.'),
 ('Wyjaśnij pojęcie: krzywa dysocjacji oksyhemoglobiny', 'Esowata zależność wysycenia hemoglobiny tlenem od ciśnienia parcjalnego O₂ — w płucach hemoglobina prawie całkowicie się wysyca, w tkankach łatwo oddaje tlen.'),
 ('Wyjaśnij pojęcie: efekt Bohra', 'Spadek powinowactwa hemoglobiny do tlenu przy wyższym stężeniu CO₂, niższym pH (i wyższej temperaturze) — krzywa przesuwa się w prawo; ułatwia oddawanie tlenu pracującym tkankom.'),
 ('Dlaczego hemoglobina płodowa ma większe powinowactwo do tlenu?', 'Umożliwia pobieranie tlenu z krwi matki w łożysku, gdzie ciśnienie parcjalne O₂ jest niskie.'),
 ('Dlaczego tlenek węgla (CO) jest trujący?', 'Wiąże się z hemoglobiną ok. 200–250 razy silniej niż tlen (karboksyhemoglobina), blokując transport tlenu.'),
 ('Wyjaśnij pojęcie: mioglobina', 'Białko mięśni magazynujące tlen; ma większe powinowactwo do O₂ niż hemoglobina, oddaje go przy bardzo niskim ciśnieniu parcjalnym (intensywny wysiłek).'),
 ('Ośrodek oddechowy — gdzie i jak reguluje oddychanie?', 'W rdzeniu przedłużonym (i moście); głównym bodźcem zwiększającym wentylację jest wzrost stężenia CO₂ (spadek pH) we krwi, wykrywany przez chemoreceptory.'),
 ('Dlaczego po hiperwentylacji można dłużej wstrzymać oddech?', 'Hiperwentylacja obniża stężenie CO₂ we krwi, a to wzrost CO₂ jest głównym bodźcem wymuszającym wdech.'),
 ('Wyjaśnij pojęcie: pojemność życiowa płuc', 'Maksymalna objętość powietrza wydychanego po maksymalnym wdechu (= objętość oddechowa + zapasowa wdechowa + zapasowa wydechowa); ok. 3,5–5 l.'),
 ('Wyjaśnij pojęcie: objętość zalegająca', 'Powietrze pozostające w płucach po maksymalnym wydechu (ok. 1–1,5 l) — nie można jej wydmuchać.'),
 ('Wyjaśnij pojęcie: przestrzeń martwa', 'Objętość dróg oddechowych, w których nie zachodzi wymiana gazowa (ok. 150 ml).'),
 ('Wpływ palenia tytoniu na układ oddechowy', 'Uszkodzenie rzęsek, nadmiar śluzu (kaszel), przewlekłe zapalenie oskrzeli, rozedma, rak płuca; CO zmniejsza transport tlenu.'),
 ('Wyjaśnij pojęcie: adaptacja do życia na dużych wysokościach', 'Wzrost liczby erytrocytów (pod wpływem erytropoetyny z nerek), większa wentylacja, więcej naczyń włosowatych i mioglobiny.'),
 ('Narządy wymiany gazowej u zwierząt', 'Powierzchnia ciała (płazińce, dżdżownica), skrzela (ryby, skorupiaki), tchawki (owady), płuca (kręgowce lądowe, pajęczaki — płucotchawki).'),
 ('Wyjaśnij pojęcie: przeciwprąd w skrzelach ryb', 'Woda i krew płyną w blaszkach skrzelowych w przeciwnych kierunkach — gradient O₂ utrzymuje się na całej długości, co pozwala pobrać do ok. 80% tlenu z wody.'),
 ('Adaptacje płuc ptaków', 'Worki powietrzne i jednokierunkowy przepływ powietrza przez płuca (parabronchy) — wymiana gazowa zarówno przy wdechu, jak i wydechu.'),
 ('Wyjaśnij pojęcie: tchawki owadów', 'System rurek doprowadzających powietrze bezpośrednio do komórek — krew (hemolimfa) nie transportuje tlenu.'),
], Q=[
 ('Podczas wdechu przepona:', ['rozkurcza się i unosi', '*kurczy się i spłaszcza', 'nie zmienia swojego położenia', 'kurczy się i unosi ku górze'], 'Zwiększenie objętości klatki.'),
 ('Najwięcej CO₂ transportowane jest we krwi jako:', ['karbaminohemoglobina', 'CO₂ rozpuszczony', '*jony wodorowęglanowe', 'karboksyhemoglobina'], 'Ok. 70%.'),
 ('Efekt Bohra polega na zmniejszeniu powinowactwa hemoglobiny do O₂ przy:', ['spadku stężenia CO₂', '*spadku pH krwi', 'spadku temperatury', 'wzroście pH krwi'], 'Ułatwia oddawanie O₂.'),
 ('Głównym bodźcem pobudzającym ośrodek oddechowy jest:', ['niewielki spadek stężenia O₂', '*wzrost stężenia CO₂ we krwi', 'wzrost pH krwi tętniczej', 'spadek temperatury ciała'], 'Chemoreceptory.'),
 ('Surfaktant:', ['transportuje tlen do krwi', '*zapobiega zapadaniu się pęcherzyków', 'oczyszcza powietrze z pyłów', 'wiąże CO₂ w pęcherzykach'], 'Obniża napięcie powierzchniowe.'),
 ('Wymiana gazowa w skrzelach ryb jest wydajna dzięki:', ['workom powietrznym połączonym z płucami', '*przeciwprądowemu przepływowi wody i krwi', 'rozgałęzionym tchawkom doprowadzającym wodę', 'surfaktantowi pokrywającemu blaszki'], 'Przeciwprąd.'),
], pp='XI.2.3')
